import{am as l,an as c,ao as h,ap as u,aq as p,ar as m,as as g,at as f,au as w,av as b,aw as v}from"./index-D2C5uoL3.js";const y=[{id:"cet4-tools",revision:1,title:"校园工具借用",description:"从词性、搭配和上下文，判断一次校园借用试点如何运行。",returnTo:"/curriculum/cet4/cet4-core-vocabulary",paragraphs:["A group of students noticed that many useful objects in their rooms were rarely used. A drill might be needed for a single afternoon, while a small set of gardening [[26]] could remain in a cupboard for months. Buying these things separately seemed wasteful. The group proposed a borrowing service that would give students [[27]] to useful items without requiring each person to own them.","Before opening the service, the organisers asked students which objects they needed most. The answers were [[28]] through a short survey, not guessed from online advertisements. There was strong [[29]] for basic tools, but very little interest in expensive machines. This helped the group choose a manageable starting collection. Each returned item was checked [[30]], with small parts inspected individually rather than being counted at a glance. Any sign of [[31]], such as a broken handle, was recorded before the item could be lent again.","The collection point opened in the evening, making the service more [[32]] for students whose classes finished late. Keeping accurate and [[33]] records was also essential: volunteers needed to know exactly who had borrowed each item and when it was due back. The project was not intended to make everyone buy more. Instead, it asked how much [[34]] could be avoided by using existing items for longer. The organisers hoped this would [[35]] students to think about borrowing before making another purchase."],words:[{id:"A",text:"access"},{id:"B",text:"additional"},{id:"C",text:"carefully"},{id:"D",text:"collected"},{id:"E",text:"convenient"},{id:"F",text:"damage"},{id:"G",text:"demand"},{id:"H",text:"encourage"},{id:"I",text:"equipment"},{id:"J",text:"regularly"},{id:"K",text:"reliable"},{id:"L",text:"replace"},{id:"M",text:"waste"},{id:"N",text:"sharply"},{id:"O",text:"temporary"}],blanks:[{number:26,answer:"I",evidence:"a small set of gardening equipment",point:"名词与类别",explanation:"gardening 限定园艺用途，equipment 表设备、用具。a set of 可以量化不可数的 equipment；后文的 tools 也与这类对象呼应。"},{number:27,answer:"A",evidence:"give students access to useful items",point:"access to 搭配",explanation:"give someone access to something 表示让某人可以使用某物。这里不是额外拥有物品，而是借用它们；to 后的 useful items 是可使用的对象。"},{number:28,answer:"D",evidence:"The answers were collected through a short survey, not guessed",point:"被动与信息收集",explanation:"were 后需要过去分词；问卷是收集回答的方式。collected 与 not guessed 对照，强调先获得需求信息，而不是凭广告猜测。"},{number:29,answer:"G",evidence:"strong demand for basic tools, but very little interest in expensive machines",point:"demand for 与对照",explanation:"strong demand for 表对某物需求很大，与后半句很少有人对昂贵机器感兴趣形成对比。damage 不表示需求，access 也不与这里的 for 构成所需搭配。"},{number:30,answer:"C",evidence:"checked carefully, with small parts inspected individually rather than being counted at a glance",point:"方式副词",explanation:"修饰 checked 要用副词。逐一检查小零件、而不是扫一眼计数，明确强调仔细的方式；regularly 只表示定期，不能概括这里解释的检查方式。"},{number:31,answer:"F",evidence:"Any sign of damage, such as a broken handle",point:"例子限定词义",explanation:"broken handle 是损坏的具体例子，因此 sign of damage 为损坏迹象。这里不是使用需求或额外资源。damage 在此是不可数名词。"},{number:32,answer:"E",evidence:"opened in the evening ... for students whose classes finished late",point:"形容词与上下文",explanation:"晚上开放使下课晚的学生更方便借用，因此用 convenient。temporary 只表示临时，不能说明晚间开放带来的时间便利。reliable 留给后文准确可信的记录。"},{number:33,answer:"K",evidence:"accurate and reliable records ... know exactly who had borrowed each item",point:"并列修饰与目的",explanation:"accurate and 后需要共同修饰 records 的形容词。必须准确知道借用者与归还时间，要求记录可靠；additional 只表示数量增加，temporary 只表示临时，都不表达可信程度。"},{number:34,answer:"M",evidence:"how much waste could be avoided by using existing items for longer",point:"不可数名词与全文主旨",explanation:"how much 后在此需要不可数名词；通过延长已有物品的使用时间可以避免浪费，因此选 waste。equipment 是用具本身，不是要避免的结果；replace 是动词，不能作这里的主语中心。"},{number:35,answer:"H",evidence:"encourage students to think about borrowing",point:"encourage someone to do",explanation:"would 后用原形，encourage students to think 表鼓励学生思考。replace 虽为动词，但 replace students to think 不能表达这一对象与不定式关系。"}],translation:["一群学生注意到，房间里不少有用的物品很少被使用。有些工具只用一下午，园艺用具可能在柜子里放上几个月。他们提出借用服务，让学生无需各自购买就能使用这些物品。","开放前，组织者用问卷收集需求，而非从广告中猜测。基本工具需求大，昂贵机器却少有人感兴趣。每件归还物品都要仔细检查，小零件逐一核对；如发现把手破损等损坏，要先记录，之后才能再次外借。","晚间取物对下课晚的学生更方便。准确可靠的记录同样重要，志愿者需要知道借用者和归还时间。项目希望通过更长久地利用现有物品减少浪费，并鼓励大家购买前先考虑借用。"]},{id:"cet4-peer-study",revision:1,title:"同伴学习记录",description:"区分印象与证据，理解同伴学习的帮助与边界。",returnTo:"/curriculum/cet4/cet4-core-vocabulary",paragraphs:["A college introduced short peer-study sessions for first-year students. The organisers did not assume that putting people in one room would automatically improve learning. In the first meeting, several participants described their [[26]] about what to do after reading a difficult chapter. They had highlighted many sentences but could not identify which ideas they needed to practise. The tutors therefore asked everyone to bring one [[27]] question rather than a general request for help.","With permission, a few discussions were [[28]] as audio so that the tutors could listen again later. These recordings provided [[29]] of how students approached a problem, rather than simply showing how long they stayed in the room. A participant might be able to repeat a definition but still struggle to [[30]] why it applied to a new example. The tutors used these differences to plan the next session. They also gave students time for [[31]] work, completed without help, to check whether they could use an idea on their own.","Extra practice sheets were made [[32]] online for anyone who wanted another attempt. Over several weeks, some students [[33]] became more willing to describe where their reasoning had gone wrong. The organisers warned against using attendance alone to decide whether learners were making [[34]]. They planned to compare the work itself and ask students about their [[35]] in handling unfamiliar tasks. The project remained a small teaching trial, not proof that peer study was the best method for every learner."],words:[{id:"A",text:"available"},{id:"B",text:"avoid"},{id:"C",text:"confidence"},{id:"D",text:"confusion"},{id:"E",text:"permission"},{id:"F",text:"effective"},{id:"G",text:"evidence"},{id:"H",text:"explain"},{id:"I",text:"gradually"},{id:"J",text:"independent"},{id:"K",text:"predict"},{id:"L",text:"progress"},{id:"M",text:"recorded"},{id:"N",text:"specific"},{id:"O",text:"support"}],blanks:[{number:26,answer:"D",evidence:"confusion about what to do ... could not identify which ideas they needed to practise",point:"解释线索",explanation:"后面解释学生不知道该练习哪些观点，说明是对下一步的困惑。confidence 是信心，与不知道如何推进的语境不一致。"},{number:27,answer:"N",evidence:"one specific question rather than a general request for help",point:"反义对照",explanation:"rather than general 明确对照具体与笼统，specific question 是一个明确问题。effective 只强调有效，不能对应本句收窄问题范围的具体／笼统对照。"},{number:28,answer:"M",evidence:"discussions were recorded as audio ... listen again later",point:"被动与方式线索",explanation:"as audio 与稍后再听共同限定录音，were recorded 是被动结构。permission 是名词，不能直接接在 were 后充当录制动作的过去分词。"},{number:29,answer:"G",evidence:"recordings provided evidence of how students approached a problem",point:"evidence of 搭配",explanation:"记录提供了解题过程的证据，而非仅记录停留时长。evidence of 表某事的证据；support 在此若使用通常需 for 等结构，不能代替 evidence of。"},{number:30,answer:"H",evidence:"struggle to explain why it applied to a new example",point:"不定式与解释任务",explanation:"to 后接原形，explain why 表解释一个原理为何适用。predict 表预测未来或未知结果，不是为已经给出的适用关系说明理由。"},{number:31,answer:"J",evidence:"independent work, completed without help ... on their own",point:"同义解释",explanation:"without help 与 on their own 都解释独立完成，因此用 independent。effective 表有效，不能直接对应不借助他人；permission 是许可这一名词，不表示独立。"},{number:32,answer:"A",evidence:"practice sheets were made available online for anyone who wanted another attempt",point:"make available 结构",explanation:"make something available 表让某物可以取得；这里给希望再练的人提供线上练习。effective 表有效，但原文并未在此报告效果。"},{number:33,answer:"I",evidence:"Over several weeks, some students gradually became more willing",point:"时间范围与副词",explanation:"Over several weeks 描述数周内的逐渐改变，gradually 修饰 became。词库里其他形容词不能直接作这里的方式、进程副词。"},{number:34,answer:"L",evidence:"whether learners were making progress",point:"make progress",explanation:"making progress 表取得进步。make confidence 不是这里的通常搭配；出勤不等于学习进步是整段的判断边界。"},{number:35,answer:"C",evidence:"ask students about their confidence in handling unfamiliar tasks",point:"confidence in doing",explanation:"confidence in handling 表处理陌生任务的信心。它是计划询问的主观感受，不等于任务能力已经获得证明；progress 已与前空 make 搭配。"}],translation:["一所学院开展短时同伴学习。组织者没有假定把人放在一起就会自动改善学习。学生说读完困难章节后不知道该做什么，因此导师让每个人带来一个具体问题，而非笼统求助。","经同意，一些讨论录成音频，供导师重听。它们提供了解题过程的证据，而不只记录停留时长。有些人能复述定义，却难以解释新例子。导师据此安排后续活动，并留出不借助他人的独立练习时间。","额外练习在线提供。数周内，一些学生逐渐愿意说明自己推理错在何处。组织者不把出勤当成进步证明，计划比较实际作业，并询问面对陌生任务的信心。项目只是小规模教学试点，不证明同伴学习对所有人最好。"]},l],x=["我回应了题面的全部任务。","每个主要观点都有解释或具体例子。","我检查了指代、主谓、时态和拼写。","修改稿至少解决了一个明确问题，未捏造来源或数据。"],k=["主体、动作、数量、时间和条件没有遗漏。","我没有增加原文没有的事实或绝对保证。","英语主谓、修饰对象和指代清楚。","我比较了初稿与修改稿，并写出修改依据。"];function t(e,a,o,r,s,d,n="writing"){return{id:e,unitId:a,title:o,source:r,reference:s,notes:d,kind:n,revision:1,suggestedWords:n==="writing"?[120,180]:[70,130],instruction:n==="writing"?"先独立写 120–180 词，再展开参考与提示，保留初稿完成修订。字数仅是训练提示，本站不自动给作文打分。":"将中文段落译为英语，先保留初稿，再核对信息与表达完成修订。参考不是唯一译法；英文 70–130 词只是本教学短段落的建议，不是官方翻译字数规定。",checklist:n==="writing"?x:k}}const T=[{id:"cet4-match-repair",revision:1,unitId:"cet4-reading-match",kind:"matching",title:"长篇匹配 · 共享维修站",instruction:"原创虚构的缩短篇幅教学材料，不是等长模拟卷。阅读 A–J 十段，为 36–45 每条陈述选出提供完整证据的段落。同一段可以重复使用，也可能有段落不被使用。十题填齐后才显示答案与解析。",paragraphs:[{id:"A",text:"The neighbourhood repair station began as a monthly table in the community hall. Residents brought broken household objects, and volunteers helped them decide whether a repair was possible. The organisers did not promise to fix every object. Their first aim was to make it easier for people to ask practical questions before throwing something away. No attendance fee was charged, although replacement parts were not always free."},{id:"B",text:"During the early meetings, several visitors arrived at the same time and waited without knowing when they would be seen. A volunteer suggested an online booking form, but the team worried that some older residents would find it difficult to use. They therefore kept telephone booking alongside the form. Both methods led to the same appointment list; using a telephone did not provide priority over online users."},{id:"C",text:"The first booking form asked only for a name and a preferred time. That left volunteers uncertain about which tools and skills would be needed. In the second month, the form added a question about the object and its problem. Residents could include a photograph, but this was optional. The organisers found that short descriptions were useful even when no photograph was supplied, because they could prepare the relevant equipment before each visit."},{id:"D",text:"Training focused on knowing the limits of a volunteer’s role. New volunteers observed an experienced member before giving advice. They were told not to open unfamiliar electrical equipment or guess about a damaged battery. If a problem required a qualified professional, they explained that limit and suggested seeking appropriate help. The team wanted visitors to understand that a community activity was not a replacement for every specialist repair service."},{id:"E",text:"In May, the station tested a separate table where visitors could learn simple maintenance skills while waiting. The table did not accept additional repair appointments. Instead, volunteers demonstrated tasks such as cleaning safe, disconnected household items and organising spare parts. The team recorded questions raised during the demonstrations so that future sessions could respond to what people actually wanted to learn rather than repeat a fixed talk."},{id:"F",text:"After three months, the organisers asked visitors to complete a short survey about the booking process. Many respondents found the appointment reminders helpful. However, the survey was completed mainly by people who had already attended. The organisers did not treat it as proof that the system suited every resident. They planned to contact people who had cancelled or had not returned, since their experiences might reveal different difficulties."},{id:"G",text:"The station kept an inventory of tools but did not initially track how long common repairs took. This made planning difficult: two visitors with apparently similar objects might need very different amounts of help. Volunteers began recording approximate task durations, without using them as guarantees for future appointments. The records were intended to improve scheduling, not to judge volunteers by how quickly they could finish a repair."},{id:"H",text:"A local school later asked whether students could join as volunteers. The station welcomed the proposal but required students to attend the same introductory training as everyone else. They also needed an experienced volunteer present during each session. The organisers rejected the suggestion that students should work alone simply because they were comfortable with technology. Confidence with a phone did not establish competence with every type of equipment."},{id:"I",text:"When the usual hall became unavailable for a month, the station moved to a smaller room in the library. Rather than accept the normal number of visitors in a crowded space, it ran two shorter sessions. Existing appointments were confirmed again, and visitors were told which session to attend. The temporary move changed the location and capacity, but telephone booking remained available throughout the month."},{id:"J",text:"At the end of the trial, the report described both successes and unresolved questions. Some items were repaired, and residents said they valued the opportunity to learn. Yet the team had not measured the project’s total environmental effect or compared it with other services. It therefore avoided claiming that every repair produced a specific saving. The next stage would collect better records while keeping the station’s practical, limited purpose clear."}],statements:[{number:36,text:"An extra description helped volunteers prepare before residents arrived.",answer:"C",evidence:"they could prepare the relevant equipment before each visit",explanation:"C 段第二个月新增物品与故障描述，帮助事先准备工具。不是 B 段仅讲预约渠道。"},{number:37,text:"A survey could not represent all local residents because most respondents had attended.",answer:"F",evidence:"the survey was completed mainly by people who had already attended",explanation:"F 段明确指出样本局限，并计划询问取消或不再来的人。好评不能外推全体。"},{number:38,text:"Students had to receive training and could not work without an experienced person present.",answer:"H",evidence:"the same introductory training ... an experienced volunteer present",explanation:"H 段同时包含培训与有经验者在场两个条件，不因熟悉科技就豁免。"},{number:39,text:"The project did not guarantee a successful repair for every object.",answer:"A",evidence:"The organisers did not promise to fix every object.",explanation:"A 段开宗明义说明范围：可以咨询和尝试，并非保证全部修好。D 段侧重专业安全边界。"},{number:40,text:"Two booking channels fed the same list without giving either channel priority.",answer:"B",evidence:"Both methods led to the same appointment list",explanation:"B 段说明电话与在线预约并行，电话不享额外优先权。I 段虽提电话保留，但没有同一列表的信息。"},{number:41,text:"Residents were not required to attach a picture to their booking.",answer:"C",evidence:"Residents could include a photograph, but this was optional.",explanation:"C 段 optional 明确照片非必需。36 与 41 可同选 C，因为对应不同的完整证据。"},{number:42,text:"The team avoided making an environmental claim that it had not measured.",answer:"J",evidence:"had not measured the project’s total environmental effect",explanation:"J 段区分实际修好物品与尚未量化的环境效果，不编造每次修理的固定节约。"},{number:43,text:"Recorded task lengths were used to plan appointments, not rank volunteer speed.",answer:"G",evidence:"improve scheduling, not to judge volunteers by how quickly",explanation:"G 段说明记录时长的目的与非目的，也指出预估不是保证。"},{number:44,text:"A temporary loss of space led to two sessions and reconfirmed appointments.",answer:"I",evidence:"it ran two shorter sessions. Existing appointments were confirmed again",explanation:"I 段包含场地缩小、分两场及重新确认预约的完整链条。"},{number:45,text:"Questions from a demonstration table would shape later learning sessions.",answer:"E",evidence:"recorded questions ... future sessions could respond",explanation:"E 段维护技能演示桌收集问题指导后续活动，而非增加维修预约。"}]},t("cet4-writing-feedback","cet4-writing-outline","写作 · 如何使用同伴反馈","Write a short essay explaining one benefit of peer feedback and suggesting how students can make it useful. Support your view with a specific example. Write 120–180 English words. Do not invent research results.",`Peer feedback can help writers notice gaps that are easy to miss when they read their own work. A writer already knows the intended message, but a new reader must depend on the words on the page.

For example, a student may write an invitation that explains the purpose of a workshop but leaves out its location. A partner can say which information is missing and why it prevents them from joining. This response gives the writer a clear reason to revise, rather than merely calling the invitation good or bad.

To make feedback useful, students should ask one or two focused questions before sharing a draft. Readers should describe their understanding and point to specific passages. The writer can then compare the comments and choose appropriate changes. Feedback works best as a conversation about communication, not as an instruction to copy another person’s style.`,["任务包含益处与使用建议，两者都需要回应。","范文用通知缺地点解释机制，不依赖虚构数据。","可用其他有效例子；不要求相同三段或相同单词。"]),t("cet4-writing-waste","cet4-writing-outline","写作 · 减少食物浪费","Write an essay suggesting one practical way a campus dining hall could reduce food waste. Explain how it would help and mention one condition needed for it to work. Write 120–180 English words.",`A campus dining hall could reduce waste by allowing students to choose smaller portions and return for more when necessary. Fixed portions can leave some students with more food than they want, while giving everyone the same amount does not reflect different needs.

A flexible system would let a student try a small serving before deciding whether to take more. For example, someone with a short lunch break might prefer a light meal, while another student could request an extra serving after finishing the first. The aim would be to match portions to actual needs, not to encourage anyone to miss a meal.

For this approach to work, the dining hall should explain the options clearly and make additional servings convenient. Staff could also collect feedback and record leftovers during a trial. These records would help the team decide what to change instead of assuming the new system must succeed.`,["措施、作用机制和实施条件均要出现。","不要把建议写成未经验证的成功数据或饮食健康承诺。","小份与可追加配套，比单纯要求所有人少吃更符合题目。"]),t("cet4-writing-agenda","cet4-writing-revise","写作修订 · 学习小组议程","Explain how a short agenda can improve a study-group meeting. Include a possible limitation and one practical suggestion. Write 120–180 English words, then revise one weak part and explain the change.",`A short agenda can help a study group use its meeting time more purposefully. When members know which questions they will discuss, they can bring relevant notes instead of spending the first part of the meeting deciding where to begin.

For example, a reading group could choose two questions that require evidence from different paragraphs. Members would first compare their answers and then discuss the passages that caused disagreement. This gives the discussion a shared focus without requiring everyone to reach the same conclusion immediately.

However, an agenda should not prevent the group from noticing an important new question. If the plan is too rigid, members may rush past a difficulty just to finish the list. A useful approach is to leave a few minutes at the end for unresolved issues. The group can then decide what deserves another meeting and record one specific task for each member.`,["观点、例子与限制需要相互关联。","范文的限制不是否定议程，而是反对过度僵化。","修订说明写清你补了什么理由或澄清了哪个指代。"]),t("cet4-writing-notice","cet4-writing-revise","写作应用 · 校园维修活动通知","Write a notice inviting students to a campus repair workshop next Saturday, 2–4 p.m., Room 105 of the Engineering Building. It accepts desk lamps and small kitchen tools, not phones or computers. Registration closes Thursday. Explain that repair is not guaranteed. Write 120–180 English words.",`Notice: Campus Repair Workshop

Students are invited to a repair workshop next Saturday from 2 to 4 p.m. in Room 105 of the Engineering Building. The session offers an opportunity to discuss small household items with volunteers and learn more about their maintenance.

You may bring a desk lamp or a small kitchen tool. Phones and computers will not be accepted. Please register by Thursday and describe the item and the problem you have noticed. This will help the volunteers prepare appropriate equipment and decide whether they can offer suitable help.

A successful repair cannot be guaranteed. Some objects may require specialist advice or replacement parts, so please do not assume every problem can be solved during the session. If you are unsure whether your item is suitable, ask the organisers before attending. Clear information in advance will make the workshop more useful for everyone.`,["核对时间、地点、物品范围和截止时间，不用议论文模板替代通知。","不能把可检修写成保证修好，不能把限定物品扩大。","题面给定的是虚构活动安排，不是真实举办公告。"]),t("cet4-translate-repair","cet4-translation-chunks","翻译 · 社区维修课堂","社区中心去年开设了维修课堂，帮助居民学习如何保养日常用品。课堂每月举行一次，由有经验的志愿者带领。参加者可以带来台灯或小型厨房工具，但需要提前说明物品的问题。并不是每件物品都能在课堂上修好。对于需要专业处理的情况，志愿者会建议居民寻求合适的帮助。活动免费，部分替换零件可能需要付费。","The community centre started repair classes last year to help residents learn how to maintain everyday items. Held once a month, the classes are led by experienced volunteers. Participants may bring desk lamps or small kitchen tools, but they need to describe the problems in advance. Not every item can be repaired during a class. When specialist work is required, volunteers advise residents to seek appropriate help. The activity is free, although some replacement parts may need to be paid for.",["last year 用过去时，常规课堂可用现在时。","并非每件都能修好，不等于每件都不能修好。","免费仅指活动，不能遗漏部分零件付费这一限制。"],"translation"),t("cet4-translate-books","cet4-translation-chunks","翻译 · 共享书架","为了让居民更方便地阅读，街区在三个公共场所设置了共享书架。居民可以免费借书，并在任意一个书架归还。志愿者每周检查书籍的状况，把损坏的书单独放置。这个项目最初计划试行三个月。组织者决定延长一个月，以便收集更多反馈，但尚未决定是否长期保留。书架不能替代图书馆，而是提供另一种接触书籍的机会。","To make reading more convenient for residents, the neighbourhood has placed shared bookshelves in three public locations. Residents can borrow books for free and return them to any of the three shelves. Volunteers check the books every week and set damaged copies aside. The project was initially planned as a three-month trial. The organisers have decided to extend it by one month to collect more feedback, but they have not decided whether to keep it permanently. The shelves do not replace libraries; they offer another way to access books.",["任意一个书架的范围是三个项目地点，不是全国任何书架。","延长一个月不等于已决定长期保留。","set damaged copies aside 与 put damaged books separately 均可考虑，核对自然度。"],"translation"),t("cet4-translate-crafts","cet4-translation-style","翻译 · 传统手工艺展","当地博物馆每年举办一次传统手工艺展，介绍剪纸和灯笼制作等活动。参观者不仅能观看作品，还可以在指导下尝试一些简单步骤。为了照顾首次接触这些工艺的人，说明牌使用清楚的语言，并附上制作过程的图片。部分体验活动需要预约，但观看展览本身免费。博物馆希望通过这种方式，让更多年轻人了解这些技艺，而不是只记住它们的名称。","The local museum holds a traditional craft exhibition once a year, introducing activities such as paper-cutting and lantern-making. Visitors can view the works and try some simple steps with guidance. To help people who are new to these crafts, the information boards use clear language and include pictures of the making process. Some hands-on activities require a reservation, but admission to the exhibition itself is free. In this way, the museum hopes to help more young people understand these skills rather than merely remember their names.",["paper-cutting 可附解释，但不要编历史年代。","部分体验需预约，展览本身免费，两个范围不同。","希望是目的，不应变成已证明所有年轻人学会。"],"translation"),t("cet4-translate-reading-room","cet4-translation-style","翻译 · 社区阅览室","这间阅览室去年完成改造，现在每周开放六天。除了提供图书，它还为居民留出安静学习的空间。工作人员根据使用者的建议调整了座位，并增加了清楚的分类标志。有些居民希望延长晚间开放时间，因此阅览室正在试行每周两次的晚间服务。试行结束后，工作人员将结合到访记录和反馈决定是否继续，而不会仅凭一次调查作出结论。","The reading room was renovated last year and is now open six days a week. In addition to providing books, it offers residents a quiet place to study. Following users’ suggestions, the staff rearranged the seats and added clear signs for different sections. Some residents wanted longer evening hours, so the reading room is testing an evening service twice a week. After the trial, the staff will consider visit records and feedback before deciding whether to continue it, rather than drawing a conclusion from a single survey.",["去年改造、目前开放、正在试行、之后决定，各有时间线。","some residents 不能改成所有居民。","一次调查不单独决定，不等于不收集调查反馈。"],"translation"),c],i=e=>e.map((a,o)=>({id:String.fromCharCode(65+o),text:a})),A=[{id:"en-mock-c4-01-cloze",revision:1,trackId:"cet4",title:"四级模拟 01 · 选词填空 · 记录身边的声音",description:"原创虚构材料 · 十五选十 · 10 空。全部提交后才显示对照和解析；这是不含听力的读写译训练卷的一部分。",returnTo:"/english/mock/cet4-paper-01",returnLabel:"回到四级读写译模拟卷",paragraphs:["A group of students began collecting recordings of everyday sounds for a class project. They wanted to [[26]] the small details of a changing neighbourhood, from a market opening in the morning to the last bus leaving at night. Before recording anyone’s voice, they asked for [[27]]. A person who agreed to a classroom recording did not necessarily agree to have it published online. Each file therefore carried a note describing how it could be used.","The first recordings were difficult to compare because the students had used different ways to name them. They adopted a format [[28]] to all members, with the date followed by the location. This made particular files easier to [[29]] when the class prepared its final presentation. A short description was stored [[30]] from the audio so that listeners could choose whether to read it first. Students also noted the distance between the microphone and the source, since a loud recording did not always mean that the original sound was [[31]].","For the presentation, each student chose one sound and explained why it seemed [[32]] to local life. The teacher asked them to support their choices with specific observations rather than general praise. The class did not treat its collection as [[33]]: many streets had not been visited, and some familiar activities had not been recorded. Keeping these [[34]] visible helped the audience understand the project’s scope. The recordings offered a starting point for further exploration, not a [[35]] for everyone’s experience of the neighbourhood."],words:i(["common","complete","find","loud","permission","preserve","relevant","separately","gaps","substitute","carelessly","arrive","narrow","refuse","wealth"]),blanks:[{number:26,answer:"F",evidence:"preserve the small details of a changing neighbourhood",point:"动词与记录目的",explanation:"to 后需动词原形。preserve 表保存变化街区的细节；find 在此不表达录制保存的目的，refuse 与珍视记录相反。"},{number:27,answer:"E",evidence:"they asked for permission",point:"授权与使用范围",explanation:"asked for permission 表征得同意，下句进一步区分课堂和网上授权。wealth 是财富，gaps 是缺口，都不能引出同意使用的范围。"},{number:28,answer:"A",evidence:"a format common to all members",point:"common to 搭配",explanation:"common to all members 表所有成员共用。complete to all members 不构成此处表示共用的搭配，narrow to all members 也不表示统一命名。日期接地点说明共同格式内容。"},{number:29,answer:"C",evidence:"easier to find",point:"不定式与检索",explanation:"格式含日期地点，让文件更容易找到，用 find。arrive 是到达，不能直接支配 particular files；preserve 是保存而非借命名检索。"},{number:30,answer:"H",evidence:"stored separately from the audio",point:"副词修饰与 from",explanation:"separately from 表与音频分开保存，给听众是否先看说明的选择。carelessly 虽为副词，但既不与 from 构成此关系，也与目的不符。"},{number:31,answer:"D",evidence:"the original sound was loud",point:"音源与录制响度",explanation:"录音响可能只是话筒距离近，未必原音本身响。loud 对应句内 loud recording；narrow 是窄，无法解释话筒距离与响度的区别。"},{number:32,answer:"G",evidence:"relevant to local life",point:"relevant to 搭配",explanation:"relevant to 表与本地生活有关，后接具体观察说明选择依据。complete to 和 loud to 均不能表达关联性的搭配与意义。"},{number:33,answer:"B",evidence:"did not treat its collection as complete",point:"后文未覆盖信息",explanation:"许多街道没去、活动没录，故不能认为全集完整 complete。common 不表达覆盖是否齐全；relevant 不能由缺少街道推出。"},{number:34,answer:"I",evidence:"Keeping these gaps visible",point:"指代与复数名词",explanation:"these 回指未采录的街道与活动，即 gaps。permission 不可数且不是这些遗漏；substitute 是替代物而不是覆盖缺口。"},{number:35,answer:"J",evidence:"not a substitute for everyone’s experience",point:"substitute for",explanation:"少量声音只是探索起点，不能替代所有人的经历，用 a substitute for。wealth 不表达替代，gaps 是复数且不适合 a。"}],translation:["学生录制街区日常声音，先问许可，课堂同意不等于网上公开许可；文件记录可用范围。","统一日期地点命名便于查找，说明与音频分开，记录话筒距离以免混淆原声与录音响度。","以具体观察说明声音与当地生活的关联；承认未覆盖的街道和活动。合集是探索起点，不替代所有人的经历。"]},{id:"en-mock-c6-01-cloze",revision:1,trackId:"cet6",title:"六级模拟 01 · 选词填空 · 解释地图上的空白",description:"原创虚构材料 · 十五选十 · 10 空。不是官方真题，也未经等难度校准；与旧日志主题选词填空使用不同材料。",returnTo:"/english/mock/cet6-paper-01",returnLabel:"回到六级读写译模拟卷",paragraphs:["When a research team mapped former workshops in a port town, it initially placed a dot wherever an address appeared in surviving records. The resulting display was visually [[26]], yet the researchers realised that a dot could conceal several different claims. It might mark a workshop documented for decades, a business mentioned once in an advertisement, or a location [[27]] from an incomplete street name.","Instead of treating these cases as equally secure, the team developed symbols that [[28]] between kinds of support. Readers could open a short account of the source behind each location. Where two records appeared to [[29]] one another, both were retained with an explanation of the disagreement. The editors resisted the temptation to force a single answer merely to make the map appear finished. They also warned that an empty area did not necessarily indicate an [[30]] of workshops. It might reflect the uneven survival of records rather than the town’s past activity.","A later discovery could require a label, a symbol and a linked source record to be [[31]] together. The team assigned responsibility for these changes rather than assuming that openness would happen [[32]]. It also kept earlier versions so that readers could follow the history of an interpretation. Such records made revision [[33]] without implying that every earlier decision had been careless.","The project did not claim that uncertainty could be eliminated by a sufficiently elaborate interface. Its more limited ambition was to make the basis of a claim [[34]] to examination. A useful map had to help readers locate places while also allowing them to question how those places had been identified. Historical knowledge was presented not as a [[35]] image immune to change, but as an account whose reliability depended partly on making its construction inspectable."],words:i(["absence","automatically","coherent","contradict","frequently","hesitation","identical","narrowly","inferred","open","permanent","traceable","updated","wealthy","distinguish"]),blanks:[{number:26,answer:"C",evidence:"visually coherent",point:"外观与证据差异",explanation:"地图看起来连贯统一 coherent，yet 引出圆点隐藏不同证据来源。permanent 强调永久，与视觉统一不同；wealthy 表富有不适用。"},{number:27,answer:"I",evidence:"a location inferred from an incomplete street name",point:"分词后置修饰",explanation:"残缺街名只能用来推断地点，inferred from 合义。updated 是更新，不表达从残缺信息推理；traceable from 也不表达该推断动作。"},{number:28,answer:"O",evidence:"symbols that distinguish between kinds of support",point:"复数先行词与动词",explanation:"复数先行词 symbols 后用 distinguish between，表示区分证据类别。contradict 表反驳且不接 between kinds of support；identical 是形容词，不能直接作此关系从句的谓语。"},{number:29,answer:"D",evidence:"records appeared to contradict one another",point:"争议解释",explanation:"后面 explanation of the disagreement 明确两记录互相冲突 contradict。distinguish 需要区别对象且不自然与 one another 表冲突；open 不符合意义。"},{number:30,answer:"A",evidence:"an absence of workshops",point:"空白与缺失",explanation:"空白不能证明过去没有作坊，用 absence of。说明可能只是资料保存不均，不能从地图未画推断历史不存在。"},{number:31,answer:"M",evidence:"to be updated together",point:"被动与信息同步",explanation:"新发现需标签、符号和来源记录同步更新 updated。inferred 是推断，不能概括这些对象需要同步维护的动作。"},{number:32,answer:"B",evidence:"openness would happen automatically",point:"副词与工作责任",explanation:"团队明确分配维护责任，而不认为公开会自动发生，选 automatically。coherent 是形容词，不能以此形式修饰 happen。"},{number:33,answer:"L",evidence:"made revision traceable",point:"修订历史可追踪",explanation:"保留旧版供读者跟踪解释历史，故 traceable。permanent 暗示永不改变，与版本修订相反；wealthy 不适合修订属性。"},{number:34,answer:"J",evidence:"open to examination",point:"固定搭配与公开检验",explanation:"open to examination 指可接受审视。traceable to examination 并无此搭配；这不是把主张固定，而是允许检查依据。"},{number:35,answer:"K",evidence:"a permanent image immune to change",point:"同义限制",explanation:"immune to change 解释不受变化影响，permanent 对应固定永久图像；coherent 仅指连贯，不能表达拒绝修订。"}],translation:["历史地图的圆点可能代表长期记录、一次广告或从残缺街名推断的地点，不能把外观统一当作证据同等确定。","符号区分证据；冲突记录都保留并说明。地图空白可能源于资料未存，不能直接证明作坊不存在。","新发现需同步更新标签、符号和来源记录，明确责任并保留旧版，让修订可追踪，不暗示以前所有判断都草率。","界面不能消除全部不确定性，但可让主张依据接受审视。可靠性部分来自建构过程可检查，不来自永远固定。"]}],q=[{id:"en-mock-c4-01-matching",revision:1,trackId:"cet4",unitId:"cet4-integration",returnTo:"/english/mock/cet4-paper-01",kind:"matching",title:"四级模拟 01 · 长篇匹配 · 让旧服装重回舞台",instruction:"原创虚构材料。阅读 A–L，为 36–45 每条陈述选择提供完整依据的段落。同段可重复，也有段落不用；提交整组后显示证据与中文辨析。",paragraphs:[{id:"A",text:"A university drama society had stored costumes in boxes behind its rehearsal room for years. Each new production bought or borrowed clothes without knowing exactly what was already there. When building work forced the society to move, members opened the boxes and found several copies of similar items. They decided to make a shared wardrobe catalogue. The purpose was to make existing clothes easier to use, not to build a museum or supply every production without additional purchases."},{id:"B",text:"The first photographs showed costumes hanging neatly against a wall. They were attractive but did not tell a borrower whether something would fit. The catalogue team added actual measurements, noting where a belt or adjustable fastening allowed flexibility. A size label from an old shop was not treated as a reliable measurement of the garment in its present condition. Members were still encouraged to try an item on before making a final choice, particularly if they needed to move energetically on stage."},{id:"C",text:"Several costumes had been altered so often that their original labels no longer described them usefully. Instead of sorting everything into historical periods, the team created practical descriptions of colour, shape and fabric. A coat might be useful in more than one kind of production. The description did not claim that wearing it would make a performance historically accurate. Directors remained responsible for deciding how an item suited their interpretation. The catalogue offered information for that decision rather than making an artistic judgement on their behalf."},{id:"D",text:"Members disagreed about whether damaged items should appear in the catalogue. Some wanted to photograph only clothes ready for immediate use. Others pointed out that a missing button was different from fabric too weak to wear safely. They agreed to show the condition of each item and mark those requiring attention before borrowing. A photograph alone could hide a problem on the inside of a garment. Written condition notes were therefore checked whenever a costume was returned, rather than being treated as permanent descriptions."},{id:"E",text:"Borrowing dates had initially meant the date of a performance. This led to a clash when two groups expected to use the same jacket during rehearsals before their shows. The booking form was changed to cover the whole period from collection to return. Groups had to include fittings, rehearsals and any cleaning time they needed. A free performance date did not automatically mean an item was available. Staff also asked borrowers to explain a changed return date promptly, since another group might already be waiting for the costume."},{id:"F",text:"The wardrobe was run by students, but its work did not happen without costs. The society needed money for storage boxes, basic repairs and cleaning products suitable for the fabrics. It decided not to charge a separate fee for each button replaced. Instead, its annual budget included routine maintenance, and borrowers were told which kinds of damage needed immediate reporting. The team did not assume that every stain resulted from carelessness. Stage work could be demanding, and useful records mattered more than assigning blame before understanding what had happened."},{id:"G",text:"To introduce the catalogue, the society arranged a short session with directors and costume volunteers. Participants searched for clothes for an imaginary scene and explained their choices. The task exposed a problem that casual browsing had missed: photographs taken under different lights made several blue garments look unrelated. The team photographed them again using the same lighting. It did not promise perfect colour on every screen, but the new pictures made comparison within the catalogue less misleading. The session tested a real decision rather than asking only whether the website looked pleasant."},{id:"H",text:"Some members proposed accepting every donation offered by former students. The storage team was less enthusiastic. An item that no group could use would still require space and checking. The society published a short list of what it currently needed and asked donors to send a description before delivering clothes. Declining an unsuitable item did not mean the donor’s memories were unimportant. It meant that an active wardrobe needed to make choices about limited space. The society suggested other possible homes for donations where appropriate, without guaranteeing that another organisation would accept them."},{id:"I",text:"One director asked to cut a borrowed coat for a particular production. The society distinguished changes that could be reversed from changes that permanently removed material. Adjustable fastenings or temporary stitching could sometimes be agreed after discussion. Cutting required explicit approval from the wardrobe team before work began. Borrowers could not assume permission simply because they were willing to return the altered item. The rule protected future uses of shared clothes while still allowing the team to consider a well-explained proposal on its own merits."},{id:"J",text:"The catalogue included contact details for the current wardrobe coordinator, but not the private phone numbers of every past borrower. A separate borrowing record was accessible only to the small group handling loans. Members could see whether an item was booked without seeing who had worn it before. This kept practical availability information public within the society while limiting unnecessary personal information. When coordinators changed at the end of the year, the new team received the working records through the society’s account, not through a departing student’s personal storage."},{id:"K",text:"At the end of the first season, the team counted how often items had been borrowed and asked groups about unsuccessful searches. Popular items were useful to know about, but low use did not automatically justify throwing something away. A highly specific costume might be valuable only occasionally. The team considered storage space, condition and possible future uses together. It also noted that borrowing an existing garment did not reveal exactly what would otherwise have been purchased, so the borrowing total was not presented as a precise measure of environmental savings."},{id:"L",text:"The society shared its catalogue template with another university, together with a description of the work involved. The receiving group could reuse field names and booking guidance, but would have to measure and photograph its own collection. Copying the first society’s records would not describe clothes in a different wardrobe. The organisers regarded the template as a useful beginning, not a finished service that could run without people. Regular checking, realistic bookings and a clear handover remained necessary even after the photographs and search page had been completed."}],statements:[{number:36,text:"Reservations had to include rehearsals and preparation rather than just the show itself.",answer:"E",evidence:"cover the whole period from collection to return",explanation:"E 段由演出日期改为完整借还时段，含试衣、排练和清洗；不是 F 段的维护预算。"},{number:37,text:"Actual dimensions were added because a label alone might not describe current fit.",answer:"B",evidence:"added actual measurements",explanation:"B 段区分旧尺码标签与服装当前实测尺寸，也建议试穿。C 段标签讨论的是分类描述而非合身尺寸。"},{number:38,text:"Irreversible alterations required specific agreement in advance.",answer:"I",evidence:"Cutting required explicit approval",explanation:"I 段剪裁会永久去料，必须提前获得服装组批准，愿意归还不等于获准。"},{number:39,text:"Donations were selected according to need and available storage.",answer:"H",evidence:"published a short list of what it currently needed",explanation:"H 段不全收捐赠，先发需求清单并要求描述；不是 A 段开箱发现重复。"},{number:40,text:"A practical search exercise revealed inconsistent lighting in the images.",answer:"G",evidence:"photographs taken under different lights",explanation:"G 段模拟真实选衣任务发现蓝色服装因灯光看似不配，于是统一重拍。"},{number:41,text:"Availability was visible without revealing previous wearers’ personal details.",answer:"J",evidence:"without seeing who had worn it before",explanation:"J 段把可用时段与限制访问的私人借用记录分开，兼顾信息与隐私。"},{number:42,text:"A low borrowing count alone did not justify discarding an item.",answer:"K",evidence:"low use did not automatically justify throwing something away",explanation:"K 段承认特殊服装可能偶用却有价值，需结合空间、状态和用途判断。"},{number:43,text:"Condition information was reviewed when clothes came back.",answer:"D",evidence:"checked whenever a costume was returned",explanation:"D 段说明照片可能藏住内部问题，归还时核对状态，不把旧说明当永久事实。"},{number:44,text:"Borrowers needed to report a delayed return because another group might need the item.",answer:"E",evidence:"Staff also asked borrowers to explain a changed return date promptly, since another group might already be waiting for the costume.",explanation:"E 段后半解释应及时告知改变的归还日期，因为下一组可能已在等；与 36 同选 E，但关注变更沟通而非原预约时段。"},{number:45,text:"Reusing a template did not remove the need to document a different collection.",answer:"L",evidence:"measure and photograph its own collection",explanation:"L 段共享字段和预约方法，但另一学校必须实测实拍自己的服装，不能复制旧藏品数据。"}]},{id:"en-mock-c6-01-matching",revision:1,trackId:"cet6",unitId:"cet6-integration",returnTo:"/english/mock/cet6-paper-01",kind:"matching",title:"六级模拟 01 · 长篇匹配 · 让旧软件中的研究仍可理解",instruction:"原创虚构材料。阅读 A–N，为 36–45 选择提供完整证据的段落。同段可重复，也有段落不用。整组提交后显示证据与辨析；不声称正式考试等难度。",paragraphs:[{id:"A",text:"A university archive received a collection of digital projects produced by researchers over two decades. The files included data tables, scripts, images and interactive demonstrations. Some could still be opened immediately; others depended on software no longer installed on the university’s computers. The archive initially described its task as keeping the files safe. Once staff began examining them, that description proved insufficient. A file could survive without anyone being able to interpret it, and a demonstration that appeared to run could still behave differently from the version its author had used."},{id:"B",text:"The team distinguished preserving a physical sequence of stored information from preserving the ability to use it meaningfully. Copying files to a maintained storage system was necessary, but it did not preserve the surrounding assumptions automatically. A table headed only with short abbreviations might be technically readable while remaining obscure. The archivists therefore asked contributors for descriptions of variables, units and missing values. This information was not treated as optional decoration added after the real preservation work. It formed part of what made the material intelligible to someone outside the original research group."},{id:"C",text:"Several contributors suggested saving screenshots of every interactive demonstration. Screenshots provided useful evidence of appearance, especially where the original software was difficult to recover. However, they did not record what happened when a user changed a setting or supplied new data. The archive kept them alongside descriptions of interaction rather than presenting them as full replacements for working examples. A picture of an output could establish that something had been displayed, but not every step through which the programme had produced it or the range of outputs it might generate."},{id:"D",text:"For a small number of important projects, technical staff reconstructed the original computing environment. They documented the operating system, programme versions and additional components needed to run the scripts. The purpose was to create an inspectable account of a particular setup, not to certify that the setup was suitable for every modern use. Old software could contain unresolved security problems. Reconstructed environments were therefore isolated from routine services, and users received clear guidance about what the archive had tested and what remained outside its responsibility."},{id:"E",text:"An alternative approach was to rewrite a project in current software. This could make it easier to maintain and more convenient for visitors. Yet apparently minor changes could affect results: a newer library might round numbers differently or handle missing values in another way. The team compared selected outputs from the old and new versions and recorded known differences. Where exact equivalence could not be established, the new version was labelled as an adaptation. Modernisation was an editorial and technical intervention, not a neutral act of moving unchanged content into a newer container."},{id:"F",text:"The archive introduced a short interview with each available contributor. Rather than asking only how a programme worked, staff asked what a result had been intended to support and which uses the contributor considered inappropriate. One researcher explained that an attractive map had illustrated a method using invented locations. Without that information, a future reader might mistake the dots for observations of real places. The team added the clarification prominently. The programme’s ability to run did not answer the historical question of what its output had meant within the original project."},{id:"G",text:"Not every contributor was available. Some had left the institution, and others could not recall details of an old project confidently. Staff recorded unanswered questions instead of filling the gaps with an elegant explanation inferred from the final report. They could sometimes establish the role of a file by comparing dates and related notes, but such reconstruction was labelled as an interpretation. A coherent story about a project was not necessarily a documented story. Maintaining that distinction allowed future discoveries to revise the account without pretending that the earlier gaps had never existed."},{id:"H",text:"The collection included participant information that had originally been gathered under limited consent. A contributor’s willingness to deposit a project did not establish permission to publish every underlying record. The archive separated public descriptions from restricted files and consulted the relevant agreements before deciding access conditions. In some cases only aggregated examples could be released. This was not a technical failure of the repository. Preserving a research record and making every part of it openly downloadable were different decisions, governed by different obligations to the people represented in the material."},{id:"I",text:"Preparing every project to the same technical level would have exceeded the available budget. The team therefore established priorities according to research value, likely use, vulnerability and the feasibility of interpretation. High download counts were not the only consideration. An obscure project might contain the sole surviving example of a method, while a popular one might already be well documented elsewhere. Decisions and their reasons were recorded so that the selection could be revisited. Choosing what to preserve first inevitably involved judgement; hiding that judgement would not make the allocation of resources more neutral."},{id:"J",text:"The public catalogue described each project’s current state in ordinary language. Some entries offered source files only, some included a recorded demonstration, and others provided a tested reconstructed environment. These categories were not a ranking of scientific merit. They told a visitor what kind of access was presently possible. Staff avoided a single ready badge, which might lead users to assume that technical availability implied complete documentation, unrestricted reuse and verified results. A more specific description required additional reading, but reduced the chance that several distinct promises would be mistaken for one."},{id:"K",text:"A pilot workshop invited historians, students and programmers to explore a few projects. Their difficulties differed. Programmers could sometimes repair an installation problem while misunderstanding a variable’s historical meaning; historians might recognise the research context but be unable to run the code. The team used these differences to improve guidance for particular tasks. It did not average the responses into a single score for ease of use. A resource could be straightforward for one reader and practically inaccessible to another, and that contrast could identify work more precisely than a favourable overall rating."},{id:"L",text:"Maintenance continued after the catalogue went online. Links stopped working, newer browsers changed behaviour and contributors supplied corrected descriptions. The archive assigned owners for routine checks and preserved earlier catalogue versions. Corrections were dated and explained where they changed an interpretation materially. Keeping this history did not require displaying every internal editing note to every visitor. It required enough information for a reader to understand why an account had changed and which version had supported an earlier citation. Stability meant managing change responsibly rather than promising that change would never occur."},{id:"M",text:"The team shared its checklist with other institutions, emphasising that it was a guide to questions rather than a universal preservation recipe. Another archive might have different legal responsibilities, technical resources and intended users. The checklist could help staff identify missing decisions, but could not make those decisions for them. Even a successfully reconstructed environment required local checking before reuse elsewhere. Sharing a procedure reduced duplicated effort most effectively when the limits of transfer travelled with the procedure, instead of disappearing from a polished description of success."},{id:"N",text:"The project changed the university’s expectations. Success meant sustaining a defensible relationship among stored material, attached explanations and offered uses, not merely accumulating files. Some projects would never become fully runnable, and new evidence could expose earlier documentation mistakes. An archive was useful not because it eliminated every obstacle to reuse, but because it made obstacles, choices and responsibilities sufficiently explicit for future people to investigate them."}],statements:[{number:36,text:"Technical readability alone did not explain variables or their measurement units.",answer:"B",evidence:"descriptions of variables, units and missing values",explanation:"B 段说明可读文件仍可能无法理解，变量、单位和缺失值说明属于可解释性工作。"},{number:37,text:"A modern version was not described as equivalent when output differences remained unresolved.",answer:"E",evidence:"labelled as an adaptation",explanation:"E 段比较新旧输出，不能确认精确一致时标为改编，不让更新软件暗示中立无变化。"},{number:38,text:"An interview prevented illustrative invented data from being mistaken for real observations.",answer:"F",evidence:"illustrated a method using invented locations",explanation:"F 段研究者说明地图使用虚构地点，代码能运行无法自动解释研究语境。"},{number:39,text:"A contributor’s willingness to deposit a project did not automatically authorise public release of participant records.",answer:"H",evidence:"did not establish permission to publish every underlying record",explanation:"H 段区分保存与公开，须核原参与者同意范围，存入者愿意不等于全部可发布；不把存档意愿增写为一份存档协议。"},{number:40,text:"Different reader groups revealed distinct barriers that a single usability score could obscure.",answer:"K",evidence:"Their difficulties differed.",explanation:"K 段程序员与历史研究者困难不同，分任务改说明而不平均成一个易用分数。"},{number:41,text:"Images of a demonstration were retained without being presented as its full functional replacement.",answer:"C",evidence:"rather than presenting them as full replacements",explanation:"C 段截图记录外观，却不能涵盖交互变化、输入和生成过程，因此只作补充。"},{number:42,text:"Restored old environments were separated from routine systems because of possible vulnerabilities.",answer:"D",evidence:"isolated from routine services",explanation:"D 段旧软件有未解安全问题，隔离环境；这不是 E 段现代改写的输出差异。"},{number:43,text:"Priority setting took account of rarity and vulnerability rather than popularity alone.",answer:"I",evidence:"the sole surviving example of a method",explanation:"I 段稀有方法和脆弱性等可优先于下载数，并记录资源分配理由。"},{number:44,text:"Dated versions enabled a reader to understand a changed account and an earlier citation.",answer:"L",evidence:"which version had supported an earlier citation",explanation:"L 段保留版本、日期与重要修订说明，稳定是负责地管理变化而非永不变化。"},{number:45,text:"Missing recollections were acknowledged rather than replaced by a convincing undocumented story.",answer:"G",evidence:"recorded unanswered questions instead of filling the gaps",explanation:"G 段贡献者失联或记忆不确时保留未知，推断标为解释，不把连贯故事当已记录事实。"}]}],I=[...y,h,...A,...u],j=[...T,p,...m,...g,...f,...w,...b,...q,...v];function E(e){return typeof e=="string"?I.find(a=>a.id===e):void 0}function S(e){return typeof e=="string"?j.find(a=>a.id===e):void 0}export{E as findBankedCloze,S as findCourseWorkshop,I as readingClozeExercises,j as readingWorkshops};
